24	/**
25	 * Collection of builtin {@link DslStoreSuppliers} for Kafka Streams. Today we
26	 * support RocksDb and InMemory stores out of the box.
27	 */
28	public class BuiltInDslStoreSuppliers {
29	
30	    public static final DslStoreSuppliers ROCKS_DB = new RocksDBDslStoreSuppliers();
31	    public static final DslStoreSuppliers IN_MEMORY = new InMemoryDslStoreSuppliers();
