33	    /**
34	     * A {@link DslStoreSuppliers} that supplies all stores backed by RocksDB
35	     */
36	    public static class RocksDBDslStoreSuppliers implements DslStoreSuppliers {
37	
38	        @Override
39	        public KeyValueBytesStoreSupplier keyValueStore(final DslKeyValueParams params) {
40	            final DslStoreFormat storeFormat = params.dslStoreFormat();
41	            switch (storeFormat) {
42	                case HEADERS:
43	                    return Stores.persistentTimestampedKeyValueStoreWithHeaders(params.name());
44	                case TIMESTAMPED:
45	                    return Stores.persistentTimestampedKeyValueStore(params.name());
46	                case PLAIN:
47	                    return Stores.persistentKeyValueStore(params.name());
48	                default:
49	                    throw new IllegalArgumentException("Unsupported DslStoreFormat: " + storeFormat +
50	                        ". Expected one of: HEADERS, TIMESTAMPED, or PLAIN");
51	            }
52	        }
53	
54	        @Override
55	        public WindowBytesStoreSupplier windowStore(final DslWindowParams params) {
56	            if (params.emitStrategy().type() == EmitStrategy.StrategyType.ON_WINDOW_CLOSE) {
57	                return RocksDbIndexedTimeOrderedWindowBytesStoreSupplier.create(
58	                        params.name(),
59	                        params.retentionPeriod(),
60	                        params.windowSize(),
61	                        params.retainDuplicates(),
62	                        params.isSlidingWindow());
63	            }
64	
65	            if (params.isTimestamped()) {
66	                return Stores.persistentTimestampedWindowStore(
67	                        params.name(),
68	                        params.retentionPeriod(),
69	                        params.windowSize(),
70	                        params.retainDuplicates());
71	            } else {
72	                return Stores.persistentWindowStore(
73	                        params.name(),
74	                        params.retentionPeriod(),
75	                        params.windowSize(),
76	                        params.retainDuplicates());
77	            }
78	        }
79	
80	        @Override
81	        public SessionBytesStoreSupplier sessionStore(final DslSessionParams params) {
82	            if (params.emitStrategy().type() == EmitStrategy.StrategyType.ON_WINDOW_CLOSE) {
83	                return new RocksDbTimeOrderedSessionBytesStoreSupplier(
84	                        params.name(),
85	                        params.retentionPeriod().toMillis(),
86	                        true);
87	            }
88	
89	            return Stores.persistentSessionStore(params.name(), params.retentionPeriod());
90	        }
91	    }
