19	import java.nio.ByteBuffer;
20	
21	/**
22	 * Marker interface to indicate that a bytes store understands the value-with-headers format
23	 * and can convert legacy timestamped value entries (ValueAndTimestamp format) to the new format.
24	 * <p>
25	 * This is analogous to {@link TimestampedBytesStore} but for header-aware stores.
26	 * <p>
27	 * Per KIP-1271, the value format is: [headersSize(varint)][headersBytes][payloadBytes]
28	 * where payloadBytes is the existing serialized value (e.g., [timestamp(8)][value] for timestamped stores).
29	 */
30	public interface HeadersBytesStore {
31	
32	    /**
33	     * Converts a legacy timestamped value (ValueAndTimestamp format, without headers) to the header-embedded format.
34	     * <p>
35	     * For timestamped stores, the legacy format is: [timestamp(8)][value]
36	     * The new format is: [headersSize(varint)][headersBytes][timestamp(8)][value]
37	     * <p>
38	     * This method adds empty headers to the existing timestamped value format.
39	     * <p>
40	     * Empty headers are represented as 0 bytes (headersSize=0, no headersBytes),
41	     *
42	     * @param valueAndTimestamp the legacy timestamped value bytes
43	     * @return the value in header-embedded format with empty headers
44	     */
45	    static byte[] convertToHeaderFormat(final byte[] valueAndTimestamp) {
46	        if (valueAndTimestamp == null) {
47	            return null;
48	        }
49	
50	        // Format: [headersSize(varint)][headersBytes][payload]
51	        // For empty headers:
52	        //   headersSize = varint(0) = [0x00]
53	        //   headersBytes = [] (empty, 0 bytes)
54	        // Result: [0x00][payload]
55	        return ByteBuffer
56	            .allocate(1 + valueAndTimestamp.length)
57	            .put((byte) 0x00)
58	            .put(valueAndTimestamp)
59	            .array();
60	    }
61	
62	    static byte[] convertFromPlainToHeaderFormat(final byte[] value) {
63	        if (value == null) {
64	            return null;
65	        }
66	
67	        // Format: [headersSize(varint)][headersBytes][timestamp(8)][payload]
68	        // For empty headers and timestamp=-1:
69	        //   headersSize = varint(0) = [0x00]
70	        //   headersBytes = [] (empty, 0 bytes)
71	        //   timestamp = -1 (8 bytes)
72	        // Result: [0x00][timestamp=-1][payload]
73	        final byte[] result = new byte[1 + 8 + value.length];
74	        result[0] = 0x00; // empty headers
75	        // timestamp = -1 (8 bytes in big-endian)
76	        result[1] = (byte) 0xFF;
77	        result[2] = (byte) 0xFF;
78	        result[3] = (byte) 0xFF;
79	        result[4] = (byte) 0xFF;
80	        result[5] = (byte) 0xFF;
81	        result[6] = (byte) 0xFF;
82	        result[7] = (byte) 0xFF;
83	        result[8] = (byte) 0xFF;
84	        System.arraycopy(value, 0, result, 9, value.length);
85	        return result;
86	    }
87	}
